-- 135: Sesame Place (both) and Playland Park (Rye) from Carter's RCDB screenshots,
-- 2026-11-05 (park names per Carter: "Sesame Place (CA) and Sesame Place (PA)"). Names as RCDB spells them ("Super Grovers Box Car Derby").
-- Sesame Place (PA) (Langhorne PA): Oscar's Wacky Taxi (Gravitykraft
--   hybrid, 2018-05-26) and Vapor Trail (custom Vekoma Junior, 1998).
-- Sesame Place (CA) (Chula Vista CA): Super Grovers Box Car Derby (Zierer
--   Force 190, 2022-03-26). Two parks share the brand, so each gets its city.
--   Both pins are ESTIMATES (missing-parks.md) until Carter sends real ones.
-- Playland Park was already here (missing-parks.md listed it wrongly). Its rows
--   get RCDB's stats: Crazy Mouse (Zamperla Zig Zag 270m, 2003), Dragon Coaster
--   (1929 woodie, 80 ft, 3,400 ft, 2:00; SBNO in 2025, not recorded), Super
--   Flight (Zamperla Volare 391m, 2004; SBNO since 2023, stored operating). New:
--   Kiddy Coaster (1928 woodie; RCDB names no maker, NAD only built the trains),
--   and three removed: Hurricane (S&MC, 1995-2003), Whirlwind (Vekoma MK-1200,
--   1984-1992) and Monster Mouse (Allan Herschell, 1967-1981). Their later homes
--   (Playcenter, Alpen Park, Knoebels, Parque Diversiones, Quassy's Mad Mouse)
--   are not in the database, so no relocation links. Edits are logged before
--   they run and only touch empty fields, so a second run changes nothing.
INSERT INTO parks (name, lat, lon, region) SELECT 'Sesame Place (PA)', 40.1846, -74.8721, 'Pennsylvania, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Sesame Place (PA)');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Oscar''s Wacky Taxi', 'Sesame Place (PA)', 'Wood', 'Gravitykraft', 'Gravitykraft Wood', 43.0, 34.0, 1205.0, 0, NULL, 2018, '2018-05-26', 'day', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Oscar''s Wacky Taxi' AND park = 'Sesame Place (PA)');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Oscar''s Wacky Taxi' AND c.park = 'Sesame Place (PA)' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Vapor Trail', 'Sesame Place (PA)', 'Steel', 'Vekoma', 'Vekoma Junior Coaster', 43.0, 27.0, 1299.2, 0, 180, 1998, '1998', 'year', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Vapor Trail' AND park = 'Sesame Place (PA)');
