INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 3, json_object('id', id, 'fields', json_array('manu', 'model', 'yr'), 'via', '135') FROM coasters WHERE name = 'Crazy Mouse' AND park = 'Playland Park' AND manu IS NULL;
UPDATE coasters SET manu = 'Zamperla', model = 'Zamperla Zig Zag', yr = 2003, opened = '2003', openedPrec = 'year' WHERE name = 'Crazy Mouse' AND park = 'Playland Park' AND manu IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 4, json_object('id', id, 'fields', json_array('h', 'l', 'dur', 'yr'), 'via', '135') FROM coasters WHERE name = 'Dragon Coaster' AND park = 'Playland Park' AND l IS NULL;
UPDATE coasters SET h = 80.0, l = 3400.0, dur = 120, inv = 0, yr = 1929, opened = '1929', openedPrec = 'year' WHERE name = 'Dragon Coaster' AND park = 'Playland Park' AND l IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 7, json_object('id', id, 'fields', json_array('manu', 'h', 's', 'l', 'inv', 'dur', 'yr'), 'via', '135') FROM coasters WHERE name = 'Super Flight' AND park = 'Playland Park' AND manu IS NULL;
UPDATE coasters SET manu = 'Zamperla', h = 50.0, s = 25.7, l = 1282.8, inv = 2, dur = 48, yr = 2004, opened = '2004', openedPrec = 'year' WHERE name = 'Super Flight' AND park = 'Playland Park' AND manu IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.park IN ('Sesame Place (PA)','Sesame Place (CA)','Playland Park') AND c.name IN ('Oscar''s Wacky Taxi','Vapor Trail','Super Grovers Box Car Derby','Kiddy Coaster','Hurricane','Whirlwind','Monster Mouse') AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
UPDATE parks SET travel = 0 WHERE name IN ('Sesame Place (PA)','Sesame Place (CA)') AND travel IS NULL;
